//! 📑️ A second metadata owner is prepared from the exact moved original and restores it before handoff or cancellation.
use super::ActionMeta;
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneSource,RetainedCloneSourceTake,RetainedCloneCursor,RetainedFieldCursor,RetainedCloneClose,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
fn built<O>(cx:&mut semio_framework_job::StepContext<'_>,output:&mut Option<O>,demand:semio_framework_job::OriginalConstructionDemand,construct:impl FnOnce()->Result<(O,semio_framework_value::RetainedCloneProgress),semio_framework_value::ValueError>)->Result<bool,semio_framework_job::OriginalTurnFailure>{semio_framework_job::admit_original_construction(cx,output,demand,|_|semio_framework_value::RetainedWorkOutcome{result:construct(),work:1})}
fn built_with<O>(cx:&mut semio_framework_job::StepContext<'_>,output:&mut Option<O>,demand:semio_framework_job::OriginalConstructionDemand,construct:impl FnOnce(&mut semio_framework_value::NativeDecodeControl<'_>)->Result<(O,semio_framework_value::RetainedCloneProgress),semio_framework_value::ValueError>)->Result<bool,semio_framework_job::OriginalTurnFailure>{semio_framework_job::admit_original_construction(cx,output,demand,|control|semio_framework_value::RetainedWorkOutcome{result:construct(control),work:1})}
fn retired(cx:&mut semio_framework_job::StepContext<'_>,demand:semio_framework_value::RetirementDemand,advance:impl FnOnce(semio_framework_value::RetainedCloneGrant)->Result<semio_framework_value::RetainedCloneStep,semio_framework_value::ValueError>)->Result<semio_framework_job::InteractiveJobCloseStep,semio_framework_job::OriginalTurnFailure>{semio_framework_job::close_original_retained_step(cx,demand,|grant|semio_framework_value::RetainedWorkOutcome{result:advance(grant),work:1})}
/// 🧷️ The owner slot remains empty only while this exact original occupies its funded source.
pub struct OriginalActionMetaCopy{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,source:ManuallyDrop<Option<RetainedCloneSource<ActionMeta>>>,admission:Option<semio_framework_value::retained_clone::RetainedCloneSourceAdmission<ActionMeta,ActionMeta,()>>,cursor:RetainedFieldCursor<ActionMeta>,output:ManuallyDrop<Option<ActionMeta>>,retirement:RetainedCloneClose,phase:u8,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"metadata copy changed its original owner, caller or receiving continuation")}
fn fixed<T>()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<T>(),depth:1,..Default::default()}}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl OriginalActionMetaCopy{
 pub fn admit(cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..fixed::<Self>()};let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;built_with(cx,output,original(d),|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::new(Self{binding,decoder,body,source:ManuallyDrop::new(None),admission:None,cursor:Default::default(),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false}),progress(d)))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn paid(cx:&mut StepContext<'_>,d:RetirementDemand)->Result<bool,OriginalTurnFailure>{let mut output=None;built(cx,&mut output,original(d),||Ok(((),progress(d))))}
 /// 🎟️ Reconciles one original issued construction grant and the child's actual work exactly once.
 fn receive(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(RetainedCloneGrant)->semio_framework_value::RetainedWorkOutcome)->Result<(),OriginalTurnFailure>{
  if cx.should_yield()||!retained_clone_grant_admits(cx.retained_grant(),d){return Ok(())}let mut work=0;let result=cx.with_native_receiving::<_,semio_framework_value_native_owned::native_decoding::NativeConstructionStepFailure<ValueError>>(|native|{let turn=native.receive_construction_step(d,|control,g|{if let Err(error)=control.charge(d.capacity_bytes){return semio_framework_value::RetainedWorkOutcome{result:Err(error),work:0}}run(g)});work=turn.work;turn.result});let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());let reconciled=cx.receiving_issued_grant().map(|g|cx.consume_receiving_retained(g,p)).transpose();cx.consume_fuel(work);match(result,reconciled){(Ok(_),Ok(_))=>Ok(()),(Err(error),Ok(_))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut error=OriginalTurnFailure::from(error);error.context_refusal=Some(receipt);Err(error)}}
 }
 /// 🪜️ Pumps bounded original funded events until readiness, caller yield or an unchanged work frontier.
 pub fn advance(&mut self,owner:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{for _ in 0..512{let before=cx.retained_progress();if self.advance_once(owner,cx)?{return Ok(true)}if cx.should_yield()||cx.retained_progress()==before{break}}Ok(false)}
 fn advance_once(&mut self,owner:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(invalid().into())}match self.phase{
  0=>{if self.admission.is_none(){if owner.is_none(){return Err(invalid().into())}self.admission=Some(RetainedCloneSource::admission_owned(owner.take().ok_or_else(invalid)?,()));}let admission=self.admission.as_ref().ok_or_else(invalid)?;let d=if admission.phase()=="ready"{fixed::<Option<RetainedCloneSource<ActionMeta>>>()}else{admission.next_demand()?};let g=cx.retained_grant();let mut done=None;built(cx,&mut done,original(d),||{let admission=self.admission.as_mut().ok_or_else(invalid)?;if admission.phase()!="ready"{let step=admission.advance(g).result?;return Ok(((),step.progress()))}let mut output=None;let step=admission.take_output(&mut output,g).result?;if output.is_some(){*self.source=output;self.admission=None;}Ok(((),step.progress()))})?;if self.source.is_some(){self.phase=1}},
  1=>{if self.cursor.output_ready(){let header=2*size_of::<Option<ActionMeta>>()+size_of::<u8>();let mut d=self.cursor.take_demand()?;d.copy_bytes=d.copy_bytes.checked_add(header).ok_or_else(invalid)?;Self::receive(cx,d,|g|{let turn=self.cursor.take(g);let result=turn.result.map(|taken|match taken{Some((meta,mut p))=>{*self.output=Some(meta);self.cursor.begin_close();self.phase=2;p.copied_bytes+=header;RetainedCloneStep::Progress(p)},None=>RetainedCloneStep::Progress(Default::default())});semio_framework_value::RetainedWorkOutcome{result,work:turn.work}})?;}else{let source=self.source.as_ref().ok_or_else(invalid)?.borrow();let d=self.cursor.advance_demands(source,self.body)?;Self::receive(cx,d,|g|self.cursor.advance(source,self.body,g))?;}},
  2=>{if self.restore(owner,cx)?&&Self::paid(cx,fixed::<u8>())?{self.phase=3}},
  3|4=>return Ok(true),_=>return Err(invalid().into())}Ok(self.phase>=3)}
 fn restore(&mut self,owner:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.cursor.begin_close();if !self.cursor.terminal_is_empty(){let d=self.cursor.close_demands(self.body)?;retired(cx,d,|g|self.cursor.close_step(g).result)?;return Ok(false)}if let Some(admission)=self.admission.as_mut(){let d=if admission.phase()=="ready"{fixed::<Option<RetainedCloneSource<ActionMeta>>>()}else{admission.next_return_demand()?};let g=cx.retained_grant();if !cx.retirement_should_yield()&&retained_clone_grant_admits(g,d){let step=if admission.phase()=="ready"{let mut output=None;let step=admission.take_output(&mut output,g).result?;if output.is_some(){*self.source=output;self.admission=None;}step}else{let mut back=None;let step=admission.return_inputs(&mut back,g).result?;if let Some((meta,()))=back{*owner=Some(meta);self.admission=None;}step};cx.consume_retained(step.progress())?;cx.consume_fuel(step.progress().copied_items as u64)}return Ok(false)}if let Some(source)=self.source.as_mut(){if owner.is_some(){return Err(invalid().into())}let d=source.next_take_demand(self.body)?;let g=cx.retained_grant();if !cx.retirement_should_yield()&&retained_clone_grant_admits(g,d){let p=match source.take_authority(g).result?{RetainedCloneSourceTake::Pending(p)=>p,RetainedCloneSourceTake::Ready(meta,p)=>{*owner=Some(meta);self.source.take();p}};cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64)}return Ok(false)}Ok(true)}
 pub fn take_into(&mut self,output:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=3||self.closing||output.is_some(){return Err(invalid().into())}if !Self::paid(cx,fixed::<Option<ActionMeta>>())?{return Ok(false)}*output=self.output.take();self.phase=4;Ok(true)}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(fixed::<u8>())}if !self.cursor.terminal_is_empty(){return self.cursor.close_demands(self.body)}if let Some(admission)=self.admission.as_ref(){return if admission.phase()=="ready"{Ok(fixed::<Option<RetainedCloneSource<ActionMeta>>>())}else{admission.next_return_demand()}}if let Some(source)=self.source.as_ref(){return source.next_take_demand(self.body)}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.output.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,self.body)}Ok(Default::default())}
 pub fn close_step(&mut self,owner:&mut Option<ActionMeta>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if !self.closing{let d=fixed::<u8>();retired(cx,d,|_|{self.closing=true;self.cursor.begin_close();Ok(RetainedCloneStep::Progress(progress(d)))})?;return Ok(false)}if !self.restore(owner,cx)?{return Ok(false)}if !self.retirement.is_empty(){let selected=self.retirement.select(self.body)?;let d=selected.demands();retired(cx,d,|g|selected.step(g).result)?;return Ok(false)}if self.output.is_some(){let d=self.retirement.next_owner_demands::<ActionMeta>(true,&None,self.body)?;retired(cx,d,|g|Ok(self.retirement.begin_granted(&mut self.output,g).result?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;return Ok(false)}Ok(true)}
 pub fn terminal_is_empty(&self)->bool{self.admission.is_none()&&self.source.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.cursor.terminal_is_empty()}
 pub fn release_demand()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalActionMetaCopy{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"metadata copy requires original restoration and paid closure")}}
